function centerCustomers(row) {
  const customers=window.CustomerTasks?.taskCustomers(row)||[];
  const assigned=window.CustomerTasks?.sortRowsForDisplay?.(customers)||ui.sortByUpdated?.(customers)||customers;
  if(row.customerSourceMode==='assigned'||assigned.length)return `<article class="panel-card"><div class="panel-header"><h2>本任务呼叫名单 · ${assigned.length} 条 ${ui.help(row.callType==='预外呼'?'名单条数包含本任务的再次联系安排，不代表去重客户数；暂停任务继续后才会呼叫。':'按已分配到本任务的客户名单统计。','名单数量说明')}</h2><div class="task-customer-toolbar">${customerImportButton(row)}${window.RepeatPredictive?.taskToolbar(row)||''}</div></div><div class="panel-body">${ui.table([{key:'name',label:'客户称呼'},{key:'phone',label:'客户号码'},...(row.callType==='预外呼'?[{key:'repeatContact',label:'联系轮次',render:meta=>'第 '+(meta?.businessContactNo||1)+' 次'}]:[]),...customerBusinessColumns(),{key:'batchName',label:'来源批次'},{key:'note',label:'联系备注'},{key:'calls',label:'最近通话结果',render:calls=>esc(calls?.length?CallState.view(calls.at(-1)).answerLabel:'未呼叫')},...(row.callType==='预外呼'&&window.RepeatPredictive?[{key:'id',label:'操作',render:(_,customer)=>RepeatPredictive.rowAction(row,customer)}]:[])],assigned)}</div></article>`;
  return `<article class="panel-card"><div class="panel-header"><div><h2>客户数据</h2><p>${esc(row.listSource)} · 共 ${row.total} 条，仅展示前 ${Math.min(row.total, 8)} 条记录</p></div><button class="btn" onclick="CloudTaskWorkspace.exportTaskCustomers('${esc(row.taskId)}')">导出当前结果</button></div><div class="panel-body no-padding">${ui.table([{key:'batchItemId',label:'批次客户编号'},{key:'phone',label:'客户号码'},{key:'status',label:'执行状态',render:v=>ui.status(v)},{key:'attempt',label:'已呼叫次数'}],customerRows(row))}</div></article>`;
}

function exportTaskCustomers(taskId) {
  const row=taskById(taskId);if(!row||!canAccessObject(row))return false;
  const customers=window.CustomerTasks?.taskCustomers(row)||[];
  if(!customers.length){showToast('当前任务没有可导出的客户明细','warning');return false;}
  return window.downloadCsv?.('任务客户明细.csv',[{key:'name',label:'客户称呼'},{key:'phone',label:'客户号码'},{key:'batchName',label:'来源批次'},{key:'externalDocumentId',label:'业务单据'},{key:'followup',label:'处理状态'},{key:'note',label:'联系备注'}],customers)||false;
}
function savedCallPriority(value) {

const sorted=(list,fallback)=>ui.sortByUpdated?.(list,fallback)||list;
function latestTime(values){return values.reduce((latest,value)=>{const time=ui.timestamp?ui.timestamp(value):typeof value==='number'?(Math.abs(value)<1e11?value*1000:value):Date.parse(value||'');return Number.isFinite(time)&&time>latest?time:latest;},0)||null;}
function rowUpdatedTime(row){return latestTime([ui.updatedTimestamp?.(row),row.updatedAt,row.updateTime,row.modifiedAt,...(row.history||[]).map(event=>event.at),...(row.calls||[]).flatMap(call=>[ui.updatedTimestamp?.(call),call.updatedAt,call.at,call.endedAt]),row.createdAt])||latestTime([row.batchUpdatedAt,row.batchCreatedAt]);}
function sortRowsForDisplay(list){return sorted(list.map(row=>({...row,localUpdatedAt:rowUpdatedTime(row)})));}

function taskExecutionCustomers(task){
  if(!guardLegacyTask(task,task,false))return null;
  if(!valid()||!task?.taskId||!AppState.authorizeObject('task.create',task)||!CloudCallData.tasks.some(t=>t.taskId===task.taskId&&t.tenantId===task.tenantId&&t.enterpriseId===task.enterpriseId))return null;
  load();return AppState.scoped(batches).filter(b=>b.tenantId===task.tenantId&&b.enterpriseId===task.enterpriseId).flatMap(b=>b.rows.filter(r=>r.taskId===task.taskId).map(r=>({...r,batchId:b.id,batchName:b.name,batchCreatedAt:b.createdAt,batchUpdatedAt:b.updatedAt,tenantId:b.tenantId,enterpriseId:b.enterpriseId,repeatCreatedBy:b.createdBy})));
}
function taskCustomers(task){return (taskExecutionCustomers(task)||[]).filter(r=>manager()||r.ownerId===ctx().accountId||r.repeatContact&&r.repeatCreatedBy===ctx().accountId);}
function open(batchId){
  const target=batchId||'', current=RouteRuntime.snapshot();
  if(current?.key==='customer-tasks'&&(current.options?.batchId||'')===target)return navigateTo('customer-tasks',{batchId:target});
  return RouteRuntime.openSecondary('customer-tasks',{batchId:target,refreshOnClose:true});
}

function sortByUpdated(rows, fallback = []) {
  return rows.map((row, index) => ({ row, index, time: updatedTimestamp(row, fallback) }))
    .sort((a, b) => (b.time ?? -Infinity) - (a.time ?? -Infinity) || a.index - b.index)
    .map(item => item.row);
}
